\begin{tikzpicture}[xscale=1.08, yscale=1.25, every node/.style={font=\normalsize}]
  % road
  \draw[->, thick] (-0.55,0) -- (8.85,0) node[right] {road};

  % interval
  \draw[very thick] (1.25,0) -- (6.75,0);
  \draw[thick] (1.25,0.22) -- (1.25,-0.22);
  \draw[thick] (6.75,0.22) -- (6.75,-0.22);

  \node[below=7pt] at (1.25,0) {\(a\)};
  \node[below=7pt] at (6.75,0) {\(b\)};
  \node[below=18pt] at (4.0,0) {interval \([a,b]\)};

  % cars: small horizontal rectangles, with gaps; denser near a, sparser near b
  \foreach \x in {1.52,1.92,2.32,2.72,3.12,3.62,4.28,5.10,6.00,6.52} {
    \draw[fill=gray!55, draw=black!75] (\x-0.11, 0.16) rectangle (\x+0.11, 0.25);
  }

  % flux only at the two endpoints, outside the interval
  \draw[very thick,->] (-0.20, 0.205) -- (1.10, 0.205);
  \node[align=center, anchor=south] at (0.45, 0.48) {\(q(a,t)\)\\enters};

  \draw[very thick,->] (6.90, 0.205) -- (8.55, 0.205);
  \node[align=center, anchor=south] at (7.72, 0.48) {\(q(b,t)\)\\leaves};

  \draw[decorate, decoration={brace, amplitude=6pt, raise=2pt}] (1.25, 0.72) -- (6.75, 0.72);
  \node[anchor=south] at (4.0, 1.55) {amount inside \(=\displaystyle\int_a^b \rho(x,t)\,dx\)};
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.80\textwidth,
